<script setup lang="ts">
import {ref} from 'vue'
import AppIcon from './AppIcon.vue'
import {ui,login} from '../store'
const username=ref(''),password=ref(''),confirm=ref(''),busy=ref(false),error=ref(''),showPassword=ref(false)
async function submit(){error.value='';if(ui.setupRequired&&password.value!==confirm.value)return error.value='两次密码不一致';busy.value=true;try{await login(username.value,password.value);password.value='';confirm.value=''}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template><main class="login-screen"><section class="login-brand"><div class="brand"><span class="brand-mark"><AppIcon name="cases" :size="25"/></span>TestPilot</div><h1>测试工作台</h1><p>编写用例、运行测试、查看报告。与 Agent 对话完成测试任务。</p><div class="login-capabilities">API · Web UI · JMeter · Android</div></section><form class="login-card" @submit.prevent="submit"><h2>{{ui.setupRequired?'创建管理员账号':'登录 TestPilot'}}</h2><p>{{ui.setupRequired?'首次使用，请设置自己的账号和密码。':'登录后继续你的项目和测试对话。'}}</p><label class="field-label">账号<input v-model="username" required minlength="3" maxlength="80" autocomplete="username" placeholder="字母、数字或下划线"/></label><label class="field-label">密码<div class="password-field"><input aria-label="密码" v-model="password" :type="showPassword?'text':'password'" required minlength="8" maxlength="128" :autocomplete="ui.setupRequired?'new-password':'current-password'" placeholder="至少 8 个字符"/><button class="icon-button" type="button" :aria-label="showPassword?'隐藏密码':'显示密码'" :aria-pressed="showPassword" @click="showPassword=!showPassword"><AppIcon name="eye" :size="17"/></button></div></label><label v-if="ui.setupRequired" class="field-label">确认密码<input v-model="confirm" type="password" required autocomplete="new-password"/></label><p v-if="error" class="login-error" role="alert">{{error}}</p><button class="button primary full-width" type="submit" :disabled="busy">{{busy?'正在登录…':ui.setupRequired?'创建并进入':'登录'}}</button></form></main></template>
